mapper.select:
SELECT YEAR, MONTH, FACTORY_CODE, PRODUCT_TYPE_CODE, MONTH_PLAN_VERSION, PRODUCTION_INIT_VERSION AS INIT_VERSION, PRODUCTION_ST_VERSION, PRODUCTION_VERSION, CREATE_TIME, IS_FINAL, PRODUCTION_START_DATE, IS_NATURAL_MONTH FROM t_mp_proc_version WHERE IFNULL(IS_DELETE, 0) = 0 AND IFNULL(PLAN_TYPE, '00') = '01' AND IFNULL(IS_SELECTED_DEMAND, 0) = 1 AND YEAR = #{year,jdbcType=DECIMAL} AND MONTH = #{month,jdbcType=DECIMAL}
AND FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
AND PRODUCT_TYPE_CODE = #{productTypeCode,jdbcType=VARCHAR}
AND MONTH_PLAN_VERSION = #{monthPlanVersion,jdbcType=VARCHAR}
AND PRODUCTION_VERSION = #{productionVersion,jdbcType=VARCHAR}
ORDER BY MONTH_PLAN_VERSION,PRODUCTION_VERSION
